-- Goblin shaman totems: Cataclysm's models (displays 30781-30784, models 3326 and 3329-3331, as in Cataclysm), converted
-- for 3.3.5 and kept in WHE-common (Creature\Spells\GoblinShamanTotem_*.m2 and their GOBLIN_SHAMANTOTEM_01* textures).
-- Model data and displays are copies of the Orc totems' rows with the goblin models; player_totem_model points the
-- Goblin race at them (sql/db-world/base/[BASE,F-023]_player_totem_model.sql).

DELETE FROM `creaturemodeldata` WHERE `id` IN (@GoblinFireTotemModel, @GoblinEarthTotemModel, @GoblinWaterTotemModel, @GoblinAirTotemModel);
INSERT INTO `creaturemodeldata` (`id`, `flags`, `model_path`, `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise`)
SELECT @GoblinFireTotemModel, `flags`, 'Creature\\Spells\\GoblinShamanTotem_Fire.m2', `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise` FROM `creaturemodeldata` WHERE `id` = 3240 /* OrcTotem_Fire */
UNION ALL
SELECT @GoblinEarthTotemModel, `flags`, 'Creature\\Spells\\GoblinShamanTotem_Earth.m2', `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise` FROM `creaturemodeldata` WHERE `id` = 3239 /* OrcTotem_Earth */
UNION ALL
SELECT @GoblinWaterTotemModel, `flags`, 'Creature\\Spells\\GoblinShamanTotem_Water.m2', `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise` FROM `creaturemodeldata` WHERE `id` = 3241 /* OrcTotem_Water */
UNION ALL
SELECT @GoblinAirTotemModel, `flags`, 'Creature\\Spells\\GoblinShamanTotem_Air.m2', `size_class`, `model_scale`, `blood_id`, `footprint_texture_id`, `footprint_texture_length`, `footprint_texture_width`, `footprint_particle_scale`, `foley_material_id`, `footstep_shake_size`, `death_thud_shake_size`, `sound_data`, `collision_width`, `collision_height`, `mount_height`, `geo_box_min_x`, `geo_box_min_y`, `geo_box_min_z`, `geo_box_max_x`, `geo_box_max_y`, `geo_box_max_z`, `world_effect_scale`, `attached_effect_scale`, `missile_collision_radius`, `missile_collision_push`, `missile_collision_raise` FROM `creaturemodeldata` WHERE `id` = 3238 /* OrcTotem_Air */;

DELETE FROM `creaturedisplayinfo` WHERE `id` IN (@GoblinFireTotem, @GoblinEarthTotem, @GoblinWaterTotem, @GoblinAirTotem);
INSERT INTO `creaturedisplayinfo` (`id`, `model_id`, `sound_id`, `extended_display_info_id`, `creature_model_scale`, `creature_model_alpha`, `texture_variation_1`, `texture_variation_2`, `texture_variation_3`, `portrait_texture_name`, `blood_level`, `blood_id`, `npc_sound_id`, `praticle_color_id`, `creature_geoset_data`, `obj_effect_package_id`)
SELECT @GoblinFireTotem, @GoblinFireTotemModel, `sound_id`, 0, `creature_model_scale`, `creature_model_alpha`, '', '', '', '', `blood_level`, `blood_id`, `npc_sound_id`, `praticle_color_id`, 0, `obj_effect_package_id` FROM `creaturedisplayinfo` WHERE `id` = @OrcFireTotem
UNION ALL
SELECT @GoblinEarthTotem, @GoblinEarthTotemModel, `sound_id`, 0, `creature_model_scale`, `creature_model_alpha`, '', '', '', '', `blood_level`, `blood_id`, `npc_sound_id`, `praticle_color_id`, 0, `obj_effect_package_id` FROM `creaturedisplayinfo` WHERE `id` = @OrcEarthTotem
UNION ALL
SELECT @GoblinWaterTotem, @GoblinWaterTotemModel, `sound_id`, 0, `creature_model_scale`, `creature_model_alpha`, '', '', '', '', `blood_level`, `blood_id`, `npc_sound_id`, `praticle_color_id`, 0, `obj_effect_package_id` FROM `creaturedisplayinfo` WHERE `id` = @OrcWaterTotem
UNION ALL
SELECT @GoblinAirTotem, @GoblinAirTotemModel, `sound_id`, 0, `creature_model_scale`, `creature_model_alpha`, '', '', '', '', `blood_level`, `blood_id`, `npc_sound_id`, `praticle_color_id`, 0, `obj_effect_package_id` FROM `creaturedisplayinfo` WHERE `id` = @OrcAirTotem;
